&=\frac{2}{a-b}\int\frac{\mathrm{d}t}
{\frac{a+b}{a-b}+t^2}\\
&=\frac{2}{a-b}\int
\frac{\mathrm{d}t}
{\left(t-\sqrt{\frac{a+b}{b-a}}\right)
\left(t+\sqrt{\frac{a+b}{b-a}}\right)}\\
&=\frac{2}{2(a-b)\sqrt{\frac{a+b}{b-a}}}
\left[
\int\frac{\mathrm{d}\left(t-\sqrt{\frac{a+b}{b-a}}\right)}
{t-\sqrt{\frac{a+b}{b-a}}}
-\int\frac{\mathrm{d}\left(t+\sqrt{\frac{a+b}{b-a}}\right)}
{t+\sqrt{\frac{a+b}{b-a}}}
\right]\\
&=-\frac{1}{\sqrt{b^2-a^2}}
\ln\left|
\frac{t-\sqrt{\frac{a+b}{b-a}}}
{t+\sqrt{\frac{a+b}{b-a}}}
\right|+C.
\end{aligned}
