=\frac{\partial u}{\partial \xi}\frac{\partial \xi}{\partial x}
+\frac{\partial u}{\partial \eta}\frac{\partial \eta}{\partial x}
=\frac{\partial u}{\partial \xi}-\frac{\partial u}{\partial \eta}，
\quad
\frac{\partial u}{\partial y}=\frac{\partial u}{\partial \eta}，
$$

$$
\frac{\partial^2u}{\partial x^2}
=\frac{\partial}{\partial \xi}\left(\frac{\partial u}{\partial \xi}-\frac{\partial u}{\partial \eta}\right)\frac{\partial \xi}{\partial x}
+\frac{\partial}{\partial \eta}\left(\frac{\partial u}{\partial \xi}-\frac{\partial u}{\partial \eta}\right)\frac{\partial \eta}{\partial x}
$$

$$
=\frac{\partial^2u}{\partial \xi^2}
-\frac{\partial^2u}{\partial \eta\partial \xi}
-\frac{\partial^2u}{\partial \xi\partial \eta}
+\frac{\partial^2u}{\partial \eta^2}
=\frac{\partial^2u}{\partial \xi^2}
-2\frac{\partial^2u}{\partial \xi\partial\eta}
+\frac{\partial^2u}{\partial \eta^2}，
$$

$$
\frac{\partial^2u}{\partial x\partial y}
=\frac{\partial}{\partial \xi}\left(\frac{\partial u}{\partial \xi}-\frac{\partial u}{\partial \eta}\right)\frac{\partial \xi}{\partial y}
+\frac{\partial}{\partial \eta}\left(\frac{\partial u}{\partial \xi}-\frac{\partial u}{\partial \eta}\right)\frac{\partial \eta}{\partial y}
=\frac{\partial^2u}{\partial \xi\partial\eta}
-\frac{\partial^2u}{\partial \eta^2}，
$$

$$
\frac{\partial^2u}{\partial y^2}=\frac{\partial^2u}{\partial \eta^2}.
$$

故

$$
\frac{\partial^2u}{\partial x^2}
+2\frac{\partial^2u}{\partial x\partial y}
+\frac{\partial^2u}{\partial y^2}
=\frac{\partial^2u}{\partial \xi^2}=0，
$$

即

$$
\frac{\partial^2u}{\partial \xi^2}=0.
$$

